const row = $input.all()[0].json;
const anomalies = [];

function check(today, avg, label) {
  const t = parseFloat(today), a = parseFloat(avg);
  if (a < 1) return;
  const ratio = t / a;
  if (ratio >= 2) anomalies.push({ type: 'spike', label, today: t, avg: a.toFixed(1), ratio: ratio.toFixed(1) });
  else if (ratio <= 0.5) anomalies.push({ type: 'drop', label, today: t, avg: a.toFixed(1), ratio: ratio.toFixed(1) });
}

check(row.visitors_today, row.visitors_avg30, 'Unikalni odwiedzajacy');
check(row.pageviews_today, row.pageviews_avg30, 'Odslony stron');
check(row.inquiries_today, row.inquiries_avg30, 'Zapytania (kalkulator)');

if (anomalies.length === 0) return [];

const today = new Date().toLocaleDateString('pl-PL');
const rows = anomalies.map(function(a) {
  const icon = a.type === 'spike' ? 'SKOK' : 'SPADEK';
  const color = a.type === 'spike' ? '#16a34a' : '#dc2626';
  return '<tr><td style="padding:8px 12px">' + a.label + '</td>'
    + '<td style="padding:8px 12px;font-weight:bold">' + a.today + '</td>'
    + '<td style="padding:8px 12px;color:#6b7280">' + a.avg + '</td>'
    + '<td style="padding:8px 12px;font-weight:bold;color:' + color + '">x' + a.ratio + ' (' + icon + ')</td></tr>';
}).join('');

const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"/><style>'
  + 'body{font-family:Arial,sans-serif;background:#f5f5f5;padding:20px}'
  + '.card{background:#fff;border-radius:8px;padding:20px;margin:10px 0;box-shadow:0 1px 3px rgba(0,0,0,.1)}'
  + 'h1{color:#dc2626;margin:0 0 4px}table{width:100%;border-collapse:collapse}'
  + 'th{background:#f9fafb;padding:8px 12px;text-align:left;font-size:12px;text-transform:uppercase;color:#6b7280}'
  + '</style></head><body>'
  + '<div class="card"><h1>ALERT AEJaCA — Anomalie Analityczne</h1>'
  + '<p style="color:#6b7280;margin:0">Wykryto ' + anomalies.length + ' anomalie - ' + today + '</p></div>'
  + '<div class="card"><table><thead><tr><th>Metryka</th><th>Dzis</th><th>Sr. 30d</th><th>Zmiana</th></tr></thead>'
  + '<tbody>' + rows + '</tbody></table></div>'
  + '<div class="card" style="background:#fef9c3"><p style="color:#92400e;font-size:13px;margin:0">'
  + 'Panel admina: https://aejaca-admin.up.railway.app/analytics</p></div>'
  + '</body></html>';

return [{ json: { html, subject: 'ALERT AEJaCA — ' + anomalies.length + ' anomalie (' + today + ')' } }];
